import { cn } from "@/lib/utils"
import type { Feature } from "@/content/site"

// AVIF/WebP variants generated by build/optimize-images.mjs from docs/screenshots.
const files = import.meta.glob("../../assets/screens/*.{avif,webp}", { eager: true, query: "?url", import: "default" }) as Record<string, string>
const widths = [640, 960, 1600]

function srcSet(name: string, format: "avif" | "webp") {
  return widths.map((w) => `${files[`../../assets/screens/${name}-${w}.${format}`]} ${w}w`).join(", ")
}

type Props = {
  name: Feature["screenshot"]
  alt: string
  /** CSS sizes attribute: the rendered width of the image. */
  sizes: string
  priority?: boolean
  className?: string
}

/** App screenshot (1600 × 1000 source) in a framed panel. Width/height are fixed to avoid layout shift. */
export function Screenshot({ name, alt, sizes, priority, className }: Props) {
  return (
    <picture className={cn("block overflow-hidden rounded-card bg-black", className)}>
      <source type="image/avif" srcSet={srcSet(name, "avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(name, "webp")} sizes={sizes} />
      <img
        src={files[`../../assets/screens/${name}-960.webp`]}
        alt={alt}
        width={1600}
        height={1000}
        loading={priority ? "eager" : "lazy"}
        decoding={priority ? "sync" : "async"}
        // React 18 only forwards the lowercase attribute name.
        {...{ fetchpriority: priority ? "high" : "auto" }}
        className="block h-auto w-full"
      />
    </picture>
  )
}
